import { CaseFile } from '../entities/case-file.entity';

/** DI token for {@link CaseFileRepository}. */
export const CASE_FILE_REPOSITORY = Symbol('CASE_FILE_REPOSITORY');

/** A case file generated by the system (HU25), as the document list shows it (`caseFile`). */
export interface CaseFileRef {
  id: number;
  version: number;
}

/** A case file once saved: its id, and who generated it as the response shows it (CA-25.9). */
export interface SavedCaseFile {
  id: number;
  generatedBy: { id: number; lastName: string; firstName: string };
}

/**
 * `case_files`: the case files the system generated. HU38 reads it to tell
 * which files of a folder are case files (the list itself is read from the
 * storage, D-100); HU25 numbers the versions and writes it.
 */
export interface CaseFileRepository {
  /** The case files among those storage ids, keyed by storage id. An id that is not one is absent. */
  findByCloudFileIds(cloudFileIds: readonly string[]): Promise<Map<string, CaseFileRef>>;

  /** The case file stored under that storage id, or `null` if the file is not one. */
  findByCloudFileId(cloudFileId: string): Promise<CaseFileRef | null>;

  /**
   * The version the next case file of the case would take: one more than the
   * highest saved, or 1. A case file deleted in the storage keeps its row, so
   * its number is never used again (CA-25.6).
   */
  nextVersion(caseId: number): Promise<number>;

  /**
   * Saves a case file just generated.
   *
   * @throws {CaseFileVersionTakenError} another case file of the case took that
   *         version first (`case_files` is unique by case and version).
   */
  save(caseFile: CaseFile): Promise<SavedCaseFile>;
}
